def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    c1 = grid[0][0]
    c2 = grid[1][0] if rows > 1 and cols > 0 else grid[0][1] if cols > 1 else None
    if c2 is None:
        return grid
    output = [[0] * cols for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            if (r + c) % 2 == 0:
                output[r][c] = c1
            else:
                output[r][c] = c2
    return output
